      const twilioWhatsAppNumber = Deno.env.get('TWILIO_WHATSAPP_NUMBER') || 'whatsapp:+14155238886'; // Twilio sandbox number

      if (twilioAccountSid && twilioAuthToken) {
        const whatsappResponse = await fetch(
          `https://api.twilio.com/2010-04-01/Accounts/${twilioAccountSid}/Messages.json`,
          {
            method: 'POST',
            headers: {
              'Authorization': 'Basic ' + btoa(`${twilioAccountSid}:${twilioAuthToken}`),
              'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: new URLSearchParams({
              From: twilioWhatsAppNumber,
              To: 'whatsapp:+221775676486',
              Body: messageContent
            })
          }
        );

        if (whatsappResponse.ok) {
          results.whatsapp.success = true;
          console.log('✅ WhatsApp message sent successfully');
        } else {
          const errorData = await whatsappResponse.json();
          results.whatsapp.error = errorData.message || 'Failed to send WhatsApp message';
          console.error('❌ WhatsApp sending failed:', errorData);
        }
      } else {
        results.whatsapp.error = 'Twilio credentials not configured';
        console.warn('⚠️ Twilio credentials not found in environment variables');
      }
    } catch (whatsappError) {
      results.whatsapp.error = whatsappError.message;
      console.error('❌ WhatsApp error:', whatsappError);
    }

    // Return results
    const overallSuccess = results.email.success || results.whatsapp.success;

    return new Response(
      JSON.stringify({
        success: overallSuccess,
        results,
        message: overallSuccess 
          ? 'Notifications envoyées avec succès' 
          : 'Échec de l\'envoi des notifications'
      }),
      {
        status: overallSuccess ? 200 : 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      }
    );
  } catch (error) {
    console.error('💥 Error in send-intercity-notifications:', error);

    return new Response(
      JSON.stringify({ 
        success: false,
        error: error.message,
        message: 'Erreur lors de l\'envoi des notifications'
      }),
      {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      }
    );
  }
});

